contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _dummy) public payable {
        require(_dummy == _dummy);

        uint balBefore = c.tokenBalance(address(this));
        uint lockedBefore = c._locked() ? 1 : 0;

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.tokenBalance(address(this));
        uint lockedAfter = c._locked() ? 1 : 0;

        if (!reverted) {
            assert(balAfter == balBefore + 20);
            assert(lockedAfter == lockedBefore);
        } else {
            assert(balAfter == balBefore);
            assert(lockedAfter == lockedBefore);
        }

        bool reverted2;
        try c.airDrop() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        assert(c._locked() == false);
        assert(!reverted2 || balAfter == 0);
    }
}

