contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 balBefore) public payable {
        // Observe the caller's balance before any state-changing call.
        uint256 before = c.tokenBalance(address(this));

        // Precondition: force the caller's balance to be a value that the test controls,
        // but we cannot set it directly; the freshly deployed c starts at 0 for us.
        // We only proceed with the positive path if the caller currently has no balance,
        // which is the documented requirement of hasNoBalance.
        // If the caller already has a balance, we use the revert path instead.
        bool reverted;
        if (before == 0) {
            // Msg.sender here is this contract; make this contract report the supported token
            // by exposing the same pure function? We cannot add another function to InvMutTest,
            // but c.airDrop() checks Bank(msg.sender).supportsToken(); msg.sender is this
            // contract, which does NOT implement supportsToken(). Thus the call will always
            // revert on the supportsToken check. That is the key guarantee we test.
            try c.airDrop() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            // The caller already has a balance, so airDrop must revert due to hasNoBalance
            // (before even reaching the token-support check).
            try c.airDrop() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        }

        // General rule: because this test contract does not implement supportsToken,
        // airDrop() must revert for every input and never change the balance.
        assert(c.tokenBalance(address(this)) == before);
    }

    receive() external payable {}
}

